function saveStringToFile(content, filename, folderId) {
  const folder = folderId
    ? DriveApp.getFolderById(folderId)
    : DriveApp.getRootFolder();

  // Check if file already exists and update it, otherwise create new
  const existing = folder.getFilesByName(filename);
  if (existing.hasNext()) {
    existing.next().setContent(content);
  } else {
    folder.createFile(filename, content, MimeType.PLAIN_TEXT);
  }
}


function updateContact2(contactData) {
  if (!contactData.resourceName) {
    throw new Error('contactData must include a resourceName');
  }

  // Step 1: Fetch the current contact
  const contact = People.People.get(contactData.resourceName, {
    personFields: 'names,emailAddresses,phoneNumbers,addresses,userDefined,metadata'
  });

  const updateFields = [];
  const updatedPerson = { etag: contact.etag };

  if (contactData.address !== undefined) {
    updatedPerson.addresses = [{
      formattedValue: contactData.address,
      type: contactData.address.type || 'home'
    }];
    updateFields.push('addresses');
  }

  if (contactData.phone !== undefined) {
    updatedPerson.phoneNumbers = [{
      value: contactData.phone,
      type:  'mobile'
    }];
    updateFields.push('phoneNumbers');
  }

  if (contactData.email !== undefined) {
    updatedPerson.emailAddresses = [{
      value: contactData.email,
      type: "Personal"
    }];
    updateFields.push('emailAddresses');
  }


  if (contactData.imageHash !== undefined) {
    const existing = (contact.userDefined || []).filter(f => f.key !== 'imageHash');
    updatedPerson.userDefined = [...existing, { key: 'imageHash', value: String(contactData.imageHash) }];
    updateFields.push('userDefined');
  }

  if (updateFields.length === 0) {
    throw new Error('No updatable fields provided');
  }

  People.People.updateContact(updatedPerson, contactData.resourceName, {
    updatePersonFields: updateFields.join(',')
  });

  if (contactData.image !== undefined) {
    const results = updateContactPhotoBase64(contactData.resourceName, contactData.image)
    console.log("results", results)
  }

  return { status: "success" };
}


function updateContact(data) {// fleshes out the stub record created by updateContacts with a photo and the date records moved in.  can only do one member at a time.
  //console.log(data)
  contacts = getContactsByLabel("Partial")
  for(const contact of contacts){
   // //console.log("contact", contact)
    for(const field of contact.userDefined){
      if(field.value === data.uuid){
        //we have found the correct contact to update

        // update the images


          updateContactPhotoBase64(contact.resourceName, data.image)
        
        // remove the "Partial" label
        const labels = getContactLabels()
        removeLabelFromContact(contact.resourceName, labels.Partial.resourceName)
        return{
          status:"success"
        }
      }
    }
  }
}

