function updateContacts(rawMembers) {// builds the initial contact record for new members with data available from a call that gets teh whole ward.  Cannot update date records moved in or the picture

  const contactsOnly = getContacts() //getContactsByLabel("Ward") 
  const labels = getContactLabels()
  labels.M=labels.Brother
  labels.F=labels.Sister
  labels.MALE=labels.Brother
  labels.FEMALE=labels.Sister
 // makeLocalWardDirectory(rawMembers)

  //get a list of former members so we can process them correctly
  const formerMembers = getContactsWhoAreFormerMembers()


  const membersOnly={}
  const membersAndContacts={}

  for(let x=0;x<rawMembers.length;x++){
    const member = rawMembers[x]
    member.index = x
    //console.log(member)
    const key=member.uuid
    let contact = contactsOnly[key]

    if(formerMembers[key]){
      // this is a member that was in the ward previously, was moved out and is now coming back in.  lets delete teh old contact so it can come in again through the normal process
      People.People.deleteContact(formerMembers[key].resourceName);
      contact=null
    }

    if(contact){
      membersAndContacts[key]={member,contact}
      delete contactsOnly[key]
    }else{
      // these are members who are new to the ward
      membersOnly[key] = member 
    }

  }
    // now, contactsOnly holds contacts that do not have a member in LCR


  console.log("contactsOnly",contactsOnly)
  console.log("membersOnly",membersOnly)

  


  //create contacts for members not in contact list yet
  createContacts(membersOnly, labels)
  //console.log("membersOnly",Object.keys(membersOnly).length,membersOnly)
  //console.log("contactsOnly",Object.keys(contactsOnly).length,contactsOnly)
  //console.log("membersAndContacts",Object.keys(membersAndContacts).length,membersAndContacts)
  console.log("contacts",JSON.stringify(contactsOnly))


  // record any one who is in the contacts only as moved out of the ward.

  const membersToUpdate = {}

  for(const[uuid, contact] of Object.entries(contactsOnly)){

    //removeLabelFromContact(contact.resourceName, labels.Partial.resourceName)

    if(!formerMembers[uuid]){ // if they are in the former members, they don't need to be marked as former members
      //console.log("contact to be marked as out of the ward", uuid, contact)
      const memberships = contact.memberships
      console.log("memberships",memberships)
      for(let x=memberships.length-1;x>=0;x--){
        console.log(x,memberships[x])
        
        // remove any groups used for members
        if([labels.Ward.resourceGroupName,labels.Brother.resourceName,labels.Sister.resourceName,labels.Partial.resourceName].includes(memberships[x].resourceGroupName)){
          memberships.splice(x,1)
        }
        memberships.push({contactGroupMembership: { contactGroupResourceName: labels.Former.resourceName}})

      }
      membersToUpdate[contact.resourceName]={
        etag:contact.etag,
        memberships
      }
      const d = new Date()
      //--//addCustomEventToContact(contact.resourceName,"Records Out", [d.getFullYear(), (d.getMonth()+1).toString().padStart(2,"0"), d.getDate().toString().padStart(2,"0")].join(""))
      
    }
  }
  
    //console.log("membersToUpdate",membersToUpdate)
  if(Object.keys(membersToUpdate).length>0){  
    const body = {
      "contacts": membersToUpdate,
      "updateMask": "memberships"
    };

    try {
      // 2. Call the People API
      const response = People.People.batchUpdateContacts(body);

    // console.log("Batch update successful!");
      //console.log(JSON.stringify(response, null, 2));
    } catch (err) {
      console.error("Batch update failed: " + err.message);
      throw err; // surface to doPost so the caller sees the failure (e.g. quota) instead of a false "success"
    }
  }

  //newly added contacts are flaged with the 'partial label'  This allows us to return all partials so they can be completed when the front end processes them one at a time.

  contacts = getContactsByLabel("Partial")

  const membersAdded=[]
  if(contacts){
    for(const contact of contacts){
      //console.log("contact",contact)
      for(const field of contact.userDefined){
        if(field.key==="uuid"){
          membersAdded.push(field.value)
          break
        }
      }
    }
  }

  

  return{
    status:"success",
    membersAdded
  }
}


