function createContacts(membersOnly, labels) {
  const contacts=[] 
  let counter=0
  for(const[uuid, member] of Object.entries(membersOnly)){
    if(++counter>10){
      console.log("counter",counter)
      batchCreateContacts(contacts)
      contacts.length = 0
    }
    contacts.push(makeContactEntry(member, labels))
    console.log(`${member.firstName} ${member.lastName} added.`)
  }
  batchCreateContacts(contacts)

  function batchCreateContacts(contacts){
    if(contacts.length>0){
      console.log("batch creating")

    const body = {
        contacts,
        "readMask": "names,emailAddresses,organizations"
      };

      try {
        const response = People.People.batchCreateContacts(body);
        console.log("contacts created:", response)
      } catch (err) {
        console.error("Batch create failed: " + err.message);
        throw err; // surface to doPost so the caller sees the failure (e.g. quota) instead of a false "success"
      }

    }
  }
}






