function getContactLabels(labels=["Sister","Brother","Ward","Partial","Former"]) {
  // Retrieve the label list using People.ContactGroups.list
  const retval={}
  const response = People.ContactGroups.list({
    groupFields: "name" // Only fetch the name of the group
  });

  for(const group of response.contactGroups){
    //console.log(group.name, group.resourceName)
    if(labels.includes(group.name)){
      retval[group.name] = group
    }
  }


  console.log("labels", retval)
  for(const label of labels){
    if(!retval[label]){
      console.log("creating", label)
      // the label does not exist, create it
      retval[label] = People.ContactGroups.create({
        "contactGroup": {
          "name": label
        }
        
      });
    } 
  }

  //console.log(retval)

  return retval
  
}

function removeLabelFromContact(resourceName,labelToRemove) {
  // const resourceName = 'people/c1234567890'; // Replace with your contact's resource name
  // const labelToRemove = 'contactGroups/1234567890'; // Replace with the group ID to remove
  
  // 1. Get the current contact details
  const person = People.People.get(resourceName, {
    personFields: 'memberships,metadata'
  });
  
  // 2. Filter out the unwanted label
  const newMemberships = person.memberships.filter(membership => {
    return membership.contactGroupMembership.contactGroupResourceName !== labelToRemove;
  });
  
  // 3. Update the contact with the new memberships array
  person.memberships = newMemberships;
  try{
  People.People.updateContact(person, resourceName, {
    updatePersonFields: 'memberships'
  });
  }catch(e){
    console.log("could not remove membership, probably because it was not in the label")
  }
  
  
}


function addLabelToContact(personResourceName, labelResourceName) {
  // 1. Get current contact data to retain existing memberships
  const person = People.People.get(personResourceName, {
    personFields: "memberships"
  });

  // 2. Prepare the updated memberships array
  const currentMemberships = person.memberships || [];
  const newMembership = {
    contactGroupMembership: {
      contactGroupResourceName: labelResourceName
    }
  };

  // 3. Combine existing with the new label
  const updatedMemberships = [...currentMemberships, newMembership];

  // 4. Update the contact
  People.People.updateContact({
    "etag": person.etag,
    "memberships": updatedMemberships
  }, personResourceName, {
    updatePersonFields: "memberships"
  });
}

function formatPhoneNumber(input) {
  var digits = String(input).replace(/\D/g, '').padStart(10, "801").slice(-10)
  return digits.replace(/(\d{3})(\d{3})(\d{4})/, "$1-$2-$3");
}

