function addCustomEventToContact(resourceName,typeName, dateString) {
  // 1. Specify the resource name of the contact
 // const resourceName = 'people/c1234567890123456789'; // Replace with your contact's ID

  // 2. Fetch current contact data to ensure we don't overwrite other fields
  const contact = People.People.get(resourceName, {
    personFields: 'events,names'
  });

 console.log("----contact", contact)
 console.log("----dateString", dateString)

  // 3. Prepare the new event object
  const newEvent = {
    "date": {
      "year": parseInt(dateString.slice(0, 4)),
      "month": parseInt(dateString.slice(4, 6)),
      "day": parseInt(dateString.slice(-2))
    },
    "type": typeName // The custom label
  };

  // 4. Update the events array
  if (!contact.events) {
    contact.events = [];
  }
  contact.events.push(newEvent);

  // 5. Save the updated contact
  People.People.updateContact(contact, resourceName, {
    updatePersonFields: 'events'
  });

  Logger.log('Custom event added successfully.');
}


