function getContactsByLabel(labelName) {
  // Step 1: Find the label ID matching the given name
  const labelsResponse = People.ContactGroups.list();
  const groups = labelsResponse.contactGroups || [];
  const group = groups.find(g => g.name === labelName);

  if (!group) {
    throw new Error(`Label "${labelName}" not found`);
  }

  // Step 2: Get the group members
  const groupDetail = People.ContactGroups.get(group.resourceName, {
    maxMembers: 1000
  });

  const memberResourceNames = groupDetail.memberResourceNames || [];
  if (memberResourceNames.length === 0) return [];

  // Step 3: Chunk into batches of 200 and fetch each
  const personFields = [
    'names',
    'emailAddresses',
    'phoneNumbers',
    'addresses',
    'birthdays',
    'organizations',
    'photos',
    'urls',
    'biographies',
    'memberships',
    'userDefined' 
  ].join(',');

  const chunkSize = 200;
  const contacts = [];

  for (let i = 0; i < memberResourceNames.length; i += chunkSize) {
    const chunk = memberResourceNames.slice(i, i + chunkSize);
    const response = People.People.getBatchGet({
      resourceNames: chunk,
      personFields
    });
    (response.responses || []).forEach(r => {
      if (r.person) contacts.push(r.person);
    });
  }

  return contacts;
}


