function listContactMemberships(resourceName) {
  const person = People.People.get(resourceName, {
    personFields: "memberships,names"
  });

  const name = person.names?.[0]?.displayName || resourceName;
  Logger.log(`Memberships for ${name}:`);

  (person.memberships || []).forEach(m => {
    if (m.contactGroupMembership) {
      const g = m.contactGroupMembership;
      Logger.log(`  ${g.contactGroupResourceName} (system: ${g.systemContactGroupId || "no"})`);
    }
  });
}